using System.Text.Json;
using Neuroset.Application;
using Neuroset.Domain;

namespace Neuroset.Tools;

public sealed class DatabaseTool(IUserDataStore store) : ITool
{
    public ToolDescriptor Descriptor { get; }=new("database","Access the isolated agent user-data store through allow-listed list/get/upsert/delete operations. The application database is never exposed.",JsonDocument.Parse("""{"type":"object","properties":{"action":{"type":"string","enum":["list","get","upsert","delete"]},"collection":{"type":"string","pattern":"^[A-Za-z0-9_.-]{1,128}$"},"key":{"type":"string","pattern":"^[A-Za-z0-9_.-]{1,128}$"},"value":{},"limit":{"type":"integer","minimum":1,"maximum":500}},"required":["action","collection"],"additionalProperties":false}""").RootElement.Clone(),ToolRisk.Write,["database.user_data"]);
    public async Task<ToolExecutionResult> ExecuteAsync(JsonElement arguments,ToolExecutionContext context,CancellationToken cancellationToken=default)
    {
        var action=arguments.GetProperty("action").GetString()!;var collection=arguments.GetProperty("collection").GetString()!;
        switch(action){case"list":return new(true,JsonSerializer.Serialize(await store.ListAsync(collection,arguments.TryGetProperty("limit",out var limit)?limit.GetInt32():100,cancellationToken).ConfigureAwait(false),DomainJson.Options));case"get":{var key=RequireKey(arguments);return new(true,JsonSerializer.Serialize(await store.GetAsync(collection,key,cancellationToken).ConfigureAwait(false),DomainJson.Options));}case"upsert":{var key=RequireKey(arguments);if(!arguments.TryGetProperty("value",out var value))return new(false,string.Empty,"value is required for upsert.");await store.UpsertAsync(new(collection,key,value.GetRawText(),DateTimeOffset.UtcNow),cancellationToken).ConfigureAwait(false);return new(true,"{\"status\":\"saved\"}");}case"delete":await store.DeleteAsync(collection,RequireKey(arguments),cancellationToken).ConfigureAwait(false);return new(true,"{\"status\":\"deleted\"}");default:return new(false,string.Empty,"Unsupported database action.");}
    }
    private static string RequireKey(JsonElement arguments)=>arguments.TryGetProperty("key",out var key)&&!string.IsNullOrWhiteSpace(key.GetString())?key.GetString()!:throw new JsonException("key is required for this action.");
}

public sealed class MemorySearchTool(IMemoryStore memory) : ITool
{
    public ToolDescriptor Descriptor { get; }=new("memory_search","Read user-visible short-term or long-term memory.",JsonDocument.Parse("""{"type":"object","properties":{"scope":{"type":"string","enum":["short_term","long_term","all"]},"query":{"type":"string"}},"additionalProperties":false}""").RootElement.Clone(),ToolRisk.Safe,["memory.read"]);
    public async Task<ToolExecutionResult> ExecuteAsync(JsonElement arguments,ToolExecutionContext context,CancellationToken cancellationToken=default){MemoryScope? scope=arguments.TryGetProperty("scope",out var s)?s.GetString() switch{"short_term"=>MemoryScope.ShortTerm,"long_term"=>MemoryScope.LongTerm,_=>null}:null;var items=await memory.ListAsync(scope,scope==MemoryScope.ShortTerm?context.ConversationId:null,cancellationToken).ConfigureAwait(false);if(arguments.TryGetProperty("query",out var query)&&!string.IsNullOrWhiteSpace(query.GetString()))items=items.Where(x=>x.Content.Contains(query.GetString()!,StringComparison.OrdinalIgnoreCase)).ToArray();return new(true,JsonSerializer.Serialize(items,DomainJson.Options));}
}

public sealed class MemoryManageTool(IMemoryStore memory,ISettingsRepository settings) : ITool
{
    public ToolDescriptor Descriptor { get; }=new("memory_manage","Save or delete an explicit, user-visible memory entry.",JsonDocument.Parse("""{"type":"object","properties":{"action":{"type":"string","enum":["remember","forget"]},"scope":{"type":"string","enum":["short_term","long_term"]},"content":{"type":"string"},"id":{"type":"string","format":"uuid"},"importance":{"type":"number","minimum":0,"maximum":1}},"required":["action"],"additionalProperties":false}""").RootElement.Clone(),ToolRisk.Write,["memory.write"]);
    public async Task<ToolExecutionResult> ExecuteAsync(JsonElement arguments,ToolExecutionContext context,CancellationToken cancellationToken=default){var action=arguments.GetProperty("action").GetString();if(action=="forget"){if(!arguments.TryGetProperty("id",out var id)||!Guid.TryParse(id.GetString(),out var memoryId))return new(false,string.Empty,"A valid memory id is required.");await memory.DeleteAsync(memoryId,cancellationToken).ConfigureAwait(false);return new(true,"{\"status\":\"deleted\"}");}var scope=arguments.TryGetProperty("scope",out var scopeElement)&&scopeElement.GetString()=="long_term"?MemoryScope.LongTerm:MemoryScope.ShortTerm;var appSettings=await settings.LoadAsync(cancellationToken).ConfigureAwait(false);if(scope==MemoryScope.LongTerm&&!appSettings.LongTermMemoryEnabled)return new(false,string.Empty,"Long-term memory is disabled in settings.");if(!arguments.TryGetProperty("content",out var content)||string.IsNullOrWhiteSpace(content.GetString()))return new(false,string.Empty,"Memory content is required.");var record=new MemoryRecord{Scope=scope,ConversationId=scope==MemoryScope.ShortTerm?context.ConversationId:null,Content=content.GetString()!,Source="agent",Importance=arguments.TryGetProperty("importance",out var importance)?importance.GetDouble():0.5};await memory.SaveAsync(record,cancellationToken).ConfigureAwait(false);return new(true,JsonSerializer.Serialize(record,DomainJson.Options));}
}

public sealed class NotificationTool(INotificationService notifications) : ITool
{
    public ToolDescriptor Descriptor { get; }=new("notify_user","Show a local Windows notification.",JsonDocument.Parse("""{"type":"object","properties":{"title":{"type":"string","minLength":1,"maxLength":100},"message":{"type":"string","minLength":1,"maxLength":500}},"required":["title","message"],"additionalProperties":false}""").RootElement.Clone(),ToolRisk.Safe,["notifications.show"]);
    public async Task<ToolExecutionResult> ExecuteAsync(JsonElement arguments,ToolExecutionContext context,CancellationToken cancellationToken=default){await notifications.ShowAsync(arguments.GetProperty("title").GetString()!,arguments.GetProperty("message").GetString()!,cancellationToken).ConfigureAwait(false);return new(true,"{\"status\":\"shown\"}");}
}

public sealed class SchedulerTool(IScheduledTaskRepository repository,ISchedulerService scheduler) : ITool
{
    public ToolDescriptor Descriptor { get; }=new("schedule_task","Create, list or delete a persistent local scheduled agent task.",JsonDocument.Parse("""{"type":"object","properties":{"action":{"type":"string","enum":["list","create","delete"]},"id":{"type":"string","format":"uuid"},"name":{"type":"string"},"prompt":{"type":"string"},"kind":{"type":"string","enum":["once","daily","weekly","interval","cron"]},"run_at":{"type":"string"},"interval_minutes":{"type":"integer","minimum":1},"day_of_week":{"type":"integer","minimum":0,"maximum":6},"time_of_day":{"type":"string"},"cron":{"type":"string"},"notify":{"type":"boolean"}},"required":["action"],"additionalProperties":false}""").RootElement.Clone(),ToolRisk.Write,["scheduler.manage"]);
    public async Task<ToolExecutionResult> ExecuteAsync(JsonElement arguments,ToolExecutionContext context,CancellationToken cancellationToken=default){var action=arguments.GetProperty("action").GetString();if(action=="list")return new(true,JsonSerializer.Serialize(await repository.ListAsync(cancellationToken).ConfigureAwait(false),DomainJson.Options));if(action=="delete"){if(!arguments.TryGetProperty("id",out var id)||!Guid.TryParse(id.GetString(),out var taskId))return new(false,string.Empty,"A valid task id is required.");await repository.DeleteAsync(taskId,cancellationToken).ConfigureAwait(false);return new(true,"{\"status\":\"deleted\"}");}if(!arguments.TryGetProperty("name",out var name)||!arguments.TryGetProperty("prompt",out var prompt))return new(false,string.Empty,"name and prompt are required.");var task=new ScheduledTaskDefinition{Name=name.GetString()!,Prompt=prompt.GetString()!,Kind=ParseKind(arguments.TryGetProperty("kind",out var kind)?kind.GetString():"once"),RunAt=arguments.TryGetProperty("run_at",out var runAt)&&DateTimeOffset.TryParse(runAt.GetString(),out var run)?run:null,IntervalMinutes=arguments.TryGetProperty("interval_minutes",out var interval)?interval.GetInt32():null,DayOfWeek=arguments.TryGetProperty("day_of_week",out var day)?(DayOfWeek)day.GetInt32():null,TimeOfDay=arguments.TryGetProperty("time_of_day",out var time)&&TimeOnly.TryParse(time.GetString(),out var parsedTime)?parsedTime:null,CronExpression=arguments.TryGetProperty("cron",out var cron)?cron.GetString():null,NotifyOnCompletion=!arguments.TryGetProperty("notify",out var notify)||notify.GetBoolean()};task.NextRunAt=scheduler.CalculateNextRun(task,DateTimeOffset.Now);await repository.SaveAsync(task,cancellationToken).ConfigureAwait(false);return new(true,JsonSerializer.Serialize(task,DomainJson.Options));}
    private static ScheduleKind ParseKind(string? value)=>value switch{"daily"=>ScheduleKind.Daily,"weekly"=>ScheduleKind.Weekly,"interval"=>ScheduleKind.Interval,"cron"=>ScheduleKind.Cron,_=>ScheduleKind.Once};
}
